from pathlib import Path
import csv,json,shutil
B=Path(__file__).resolve().parent
for name in ['decisions.csv','clauses.csv']:
 p=B/name; orig=B/(name+'.blank-v1');
 if not orig.exists(): shutil.copyfile(p,orig)

def edit(name,fun):
 p=B/name
 with p.open(newline='') as f:r=csv.DictReader(f);fields=r.fieldnames;rows=list(r)
 for row in rows:fun(row)
 with p.open('w',newline='') as f:w=csv.DictWriter(f,fields);w.writeheader();w.writerows(rows)
reason="EO10704 contains exactly two operative paragraphs: membership and the conforming amendment to parent EO10673 section1. Its hereafter membership rule took effect on signing1957-03-25; no deferred date, report deadline, sunset, contingent completion, or separate command appears. EO10740 and10785 later change the membership, continued amended under the owner2026-10-21 strike-and-insert ruling. Reusing the carried Sinclair cross-family correction, the earlier-displacement theory is rejected; these are later events, not first endings. EO10931 section2 expressly and unconditionally revokes EO10704 by number and date, with no delayed commencement or savings; both paragraphs therefore end1961-03-29. Its section1 installs the next parent membership, distinct from the target's revocation. Complete official pages of10704,10740,10785,10931,10673,10772,11074 were independently inspected in this producer context. EO10673's reporting/agency assistance/advisory duties belong to the parent, not an unlisted EO10704 command. EO10772 changes only parent section4. EO11074 sections3-4 preserve independent agency functions and Council institutional continuity; section6 revokes10673/10772/10931 without restoring10704. This preserves institutional history without treating continued Council existence as continued target authority. The status remains the adopted provisional NO; prior status reviews do not approve this whole lifecycle. Held OCR is quoted exactly including harmless recognition artifacts and was compared with retained page images. Bounded search coverage and complete source pins are recorded in RESEARCH.v1.md and SOURCE_MANIFEST.v1.json beside the packet; no universal absence claim or human certification is made."
savings="Neither EO10704 nor EO10931 saves a target clause, delegation, individual right, pending proceeding, accrued payment, property transfer, or unresolved duty. The original only resets the Council's membership and conforms parent section1. Parent EO10673 sections2-7 continue their own functions until their later disposition; EO11074 section4 expressly continues the institution in1963 and section3(a) protects independent statutory agency functions. Those are disclosed institutional/independent effects, not surviving EO10704 membership authority. Revocation of10931 in1963 contains no restoration of10704. No target-specific continuing residual was found in the bounded held-corpus/OFR/current-law searches; USC coverage stops2026-10-09, while the CFR and OFR searches cover the2026-10-14 cutoff."
def decision(r):
 r.update(outcome='submit',approved='true',original_confirmed='true',original_pages_confirmed='true',inventory_confirmed='true',research_rationale=reason,savings_state='none_after_bounded_search',savings_source_id='ACTOR_TEXT:EO:10931',savings_reason=savings,search_ids=json.dumps(['current-law:usc','current-law:ecfr','later-events:ofr_catalog']),conflict_resolutions='{}',unresolved_material_gaps='[]',earlier_end_check='Read full original and10740/10785: no sunset or performance contingency. Reject earlier membership-displacement ending under owner strike-and-insert rule and carried cross-family correction. Direct named revocation10931 sec2 is first cessation1961-03-29; later parent ending11074 does not postpone it.',scope_check='Complete inventory is paragraphs1 and2; preamble/title/signature are not additional commands. Parent duties in10673 sections2-7 and10772 advisory amendment are not newly imposed by10704.',independent_command_check='No separate report, transfer, savings, implementation or deadline command in10704; paragraph2 is the conforming parent amendment, expressly included and not treated as instantly spent.',savings_check=savings)
 # All selected source references are official FR originals, not derivative alternatives.
 r['working_text']=''
