mid='Secretary of the Interior (chair); Secretaries of Defense, Agriculture, Labor, and Health, Education, and Welfare.'
new='Secretary of the Interior (chair); Secretaries of Defense, Agriculture, Commerce, Labor, and Health, Education, and Welfare; Housing and Home Finance Administrator.'
events=[{'id':'ACTOR_TEXT:EO:10740','effective_date':'1957-11-21','effective_date_confirmed':True,'mechanism':'Membership amendment continuing amended under owner strike-and-insert ruling; EO10740 paragraphs1-2. Before: '+old+' After: '+mid+' Substantive composition/chair change; not a cessation.'},{'id':'ACTOR_TEXT:EO:10785','effective_date':'1958-10-17','effective_date_confirmed':True,'mechanism':'Membership amendment continuing amended under owner strike-and-insert ruling; EO10785 paragraphs1-2. Before: '+mid+' After: '+new+' Substantive composition change; not a cessation.'}]
def clause(r):
 r.update(state='terminated',end_id='ACT:EO:10704>EO:10931',effective_date='1961-03-29',effective_date_confirmed='true',later_event_ids='[]',later_events=json.dumps(events),reason=('Paragraph1 membership mandate' if r['scope_id'].endswith('#1') else 'Paragraph2 conforming amendment of parent section1')+' continues amended through10740/10785, rather than ending on the changed membership or immediate execution of the amendment. Both are expressly revoked by10931 sec2 on1961-03-29. No separate deadline, savings or performance condition; no deferred effectiveness. Original membership/parent linkage and both after-texts are retained in the later events.')
